<?php
require __DIR__.'/../config/config.php'; require_admin();
$action=$_GET['action']??''; $id=(int)($_GET['id']??0); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$title=trim($_POST['title']);$desc=trim($_POST['description']);$date=$_POST['notice_date'];$status=$_POST['status'];if($id){$s=db()->prepare("UPDATE notices SET title=?,description=?,notice_date=?,status=? WHERE id=?");$s->execute([$title,$desc,$date,$status,$id]);}else{$s=db()->prepare("INSERT INTO notices(title,description,notice_date,status) VALUES(?,?,?,?)");$s->execute([$title,$desc,$date,$status]);}$msg='Notice saved.';$action='';}
if($action==='delete'&&$id){$s=db()->prepare("DELETE FROM notices WHERE id=?");$s->execute([$id]);header('Location:notices.php');exit;}
$edit=$id?db()->prepare("SELECT * FROM notices WHERE id=?"):null;if($edit){$edit->execute([$id]);$row=$edit->fetch();}else{$row=['id'=>0,'title'=>'','description'=>'','notice_date'=>date('Y-m-d'),'status'=>'published'];}
$rows=db()->query("SELECT * FROM notices ORDER BY notice_date DESC,id DESC")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notices</title><link rel="stylesheet" href="admin.css"></head><body><div class="layout"><aside class="side"><h2>GBU ADMIN</h2><a href="index.php">Dashboard</a><a class="active" href="notices.php">Notices</a><a href="courses.php">Courses</a><a href="events.php">Events</a><a href="admins.php">Admins</a><a href="logout.php">Logout</a></aside><main class="main"><div class="top"><h1>Notices</h1><a class="button gold" href="notices.php?action=new">+ New</a></div><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($action==='new'||$id):?><div class="panel"><h2><?= $id?'Edit':'Add' ?> Notice</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e((string)$row['id'])?>"><label>Title</label><input name="title" required value="<?=e($row['title'])?>"><label>Description</label><textarea name="description" rows="5"><?=e($row['description'])?></textarea><div class="formgrid"><div><label>Date</label><input type="date" name="notice_date" required value="<?=e($row['notice_date'])?>"></div><div><label>Status</label><select name="status"><option value="published" <?=$row['status']==='published'?'selected':''?>>Published</option><option value="draft" <?=$row['status']==='draft'?'selected':''?>>Draft</option></select></div></div><button class="button gold">Save</button> <a class="button" href="notices.php">Cancel</a></form></div><?php endif;?><div class="panel"><table class="table"><tr><th>Title</th><th>Date</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['notice_date'])?></td><td><?=e($r['status'])?></td><td><a class="button" href="?id=<?=$r['id']?>">Edit</a> <a class="button danger" onclick="return confirm('Delete?')" href="?action=delete&id=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></table></div></main></div></body></html>